"""
Git CLI operations for the GitHub Specialist Agent.
Wraps git subprocess commands with error handling and guardrails.
"""
import subprocess
import os
from pathlib import Path
from datetime import datetime

GitOperationError = type("GitOperationError", (Exception,), {})


class GitOps:
    """Thin wrapper around git CLI for a single repository."""

    def __init__(self, repo_path: str):
        self._path = Path(repo_path).resolve()
        if not (self._path / ".git").exists():
            raise GitOperationError(f"Not a git repository: {repo_path}")

    def _run(self, *args: str) -> subprocess.CompletedProcess:
        """Run a git command in the repo directory."""
        return subprocess.run(
            ["git"] + list(args),
            cwd=str(self._path),
            capture_output=True,
            text=True,
            shell=False,
            timeout=60,
        )

    def _require_zero(self, cp: subprocess.CompletedProcess, msg: str = None):
        """Raise GitOperationError if subprocess return code is non-zero."""
        if cp.returncode != 0:
            detail = msg or cp.stderr.strip() or cp.stdout.strip()
            raise GitOperationError(f"git error: {detail}")

    # -- status --

    def status(self) -> dict:
        """Return structured git status: branch, modified, staged, untracked."""
        branch = self.branch_current()
        cp = self._run("status", "--porcelain")
        lines = [l for l in cp.stdout.split("\n") if l.strip()]
        staged = []
        modified = []
        untracked = []
        for line in lines:
            code = line[:2]
            filepath = line[3:].strip()
            if code == "??":
                untracked.append(filepath)
            elif code[0] != " ":
                staged.append(filepath)
            else:
                modified.append(filepath)
        # ahead/behind
        cp2 = self._run("rev-list", "--left-right", "--count",
                        f"{branch}...{branch}@{{upstream}}")
        ahead = behind = 0
        if cp2.returncode == 0 and cp2.stdout.strip():
            parts = cp2.stdout.strip().split("\t")
            if len(parts) == 2:
                ahead, behind = int(parts[0]), int(parts[1])
        return {
            "branch": branch,
            "staged": staged,
            "modified": modified,
            "untracked": untracked,
            "ahead": ahead,
            "behind": behind,
        }

    def branch_current(self) -> str:
        """Return the current branch name."""
        cp = self._run("rev-parse", "--abbrev-ref", "HEAD")
        self._require_zero(cp)
        return cp.stdout.strip()

    def branch_list(self) -> list:
        """Return list of branches with current marker."""
        cp = self._run("branch")
        self._require_zero(cp)
        branches = []
        for line in cp.stdout.split("\n"):
            line = line.strip()
            if not line:
                continue
            is_current = line.startswith("*")
            name = line.lstrip("* ").strip()
            branches.append({"name": name, "current": is_current})
        return branches

    def branch_create(self, name: str, base: str = None) -> dict:
        """Create a new branch from base (or HEAD)."""
        args = ["branch", name]
        if base:
            args.extend([base])
        cp = self._run(*args)
        self._require_zero(cp)
        return {"branch": name, "base": base or "HEAD"}

    def branch_delete(self, name: str, force: bool = False) -> dict:
        """Delete a branch. Raises if unmerged unless force=True."""
        args = ["branch", "-d" if not force else "-D", name]
        cp = self._run(*args)
        self._require_zero(cp)
        return {"deleted": name}

    # -- staging and commit --

    def add(self, paths: list = None) -> dict:
        """Stage files. Defaults to all changes."""
        if paths:
            self._run("add", "--", *paths)
        else:
            self._run("add", "--all")
        return {"staged": paths or "all"}

    def commit(self, message: str, author: str = None) -> dict:
        """Create a commit. Returns hash and files_changed."""
        args = ["commit", "-m", message]
        if author:
            args.extend(["--author", author])
        cp = self._run(*args)
        self._require_zero(cp)
        # Parse output for hash and files
        out = cp.stdout.strip()
        lines = out.split("\n")
        hash_line = next((l for l in lines if l.startswith("[")), "")
        hash_val = hash_line.split("]")[0].split()[-1] if "]" in hash_line else ""
        return {"hash": hash_val, "message": message, "output": out}

    def log(self, n: int = 10) -> dict:
        """Return recent commits."""
        fmt = "--format=%H||%an||%ae||%ai||%s"
        cp = self._run("log", f"-{n}", fmt)
        self._require_zero(cp)
        commits = []
        for line in cp.stdout.strip().split("\n"):
            if not line:
                continue
            parts = line.split("||", 4)
            if len(parts) == 5:
                commits.append({
                    "hash": parts[0],
                    "author": parts[1],
                    "email": parts[2],
                    "date": parts[3],
                    "message": parts[4],
                })
        return {"commits": commits, "count": len(commits)}

    # -- sync operations --

    def pull(self, remote: str = "origin", branch: str = None) -> dict:
        """Pull from remote."""
        args = ["pull", remote]
        if branch:
            args.append(branch)
        cp = self._run(*args)
        self._require_zero(cp)
        return {"output": cp.stdout.strip()}

    def push(self, remote: str = "origin", branch: str = None,
             force: bool = False, allow_force: bool = False) -> dict:
        """Push to remote. Guardrail: refuses force push on main/master."""
        current = branch or self.branch_current()
        if force and current in ("main", "master") and not allow_force:
            raise GitOperationError(
                f"Guardrail: force push refused on '{current}'. "
                f"Set allow_force=True to override."
            )
        args = ["push", remote, current or "HEAD"]
        if force:
            args.insert(1, "--force")
        cp = self._run(*args)
        self._require_zero(cp)
        return {"output": cp.stdout.strip()}

    def has_uncommitted(self) -> bool:
        """Check if there are uncommitted changes."""
        cp = self._run("status", "--porcelain")
        return bool(cp.stdout.strip())

    def diff(self) -> str:
        """Return unstaged diff."""
        cp = self._run("diff")
        return cp.stdout

    # -- repository operations --

    @classmethod
    def clone(cls, url: str, path: str, branch: str = None) -> "GitOps":
        """Clone a repository and return GitOps instance."""
        args = ["clone", url, path]
        if branch:
            args.extend(["--branch", branch])
        cp = subprocess.run(args, capture_output=True, text=True, timeout=300)
        if cp.returncode != 0:
            raise GitOperationError(f"clone failed: {cp.stderr.strip()}")
        return cls(path)

    @classmethod
    def init(cls, path: str) -> "GitOps":
        """Initialize a new git repository."""
        Path(path).mkdir(parents=True, exist_ok=True)
        cp = subprocess.run(
            ["git", "init"],
            cwd=path, capture_output=True, text=True, timeout=30,
        )
        if cp.returncode != 0:
            raise GitOperationError(f"init failed: {cp.stderr.strip()}")
        return cls(path)

    # -- worktree operations --

    def worktree_add(self, path: str, branch: str) -> dict:
        """Add a git worktree."""
        cp = self._run("worktree", "add", path, branch)
        self._require_zero(cp)
        return {"path": path, "branch": branch}

    def worktree_list(self) -> list:
        """List worktrees."""
        cp = self._run("worktree", "list", "--porcelain")
        self._require_zero(cp)
        entries = []
        current = {}
        for line in cp.stdout.strip().split("\n"):
            if not line:
                if current:
                    entries.append(current)
                    current = {}
                continue
            if line.startswith("worktree "):
                current["path"] = line[9:]
            elif line.startswith("HEAD "):
                current["head"] = line[5:]
            elif line.startswith("branch "):
                current["branch"] = line[7:]
            elif line.startswith("detached"):
                current["detached"] = True
        if current:
            entries.append(current)
        return entries

    def last_commit_time(self) -> datetime:
        """Return datetime of the last commit."""
        cp = self._run("log", "-1", "--format=%cI")
        self._require_zero(cp)
        raw = cp.stdout.strip()
        return datetime.fromisoformat(raw) if raw else datetime.min

