         self._require_zero(self._run(*args))
         return {"output": "ok"}

     def has_uncommitted(self) -> bool:
         cp = self._run("status", "--porcelain")
         return bool(cp.stdout.strip())

     def diff(self) -> str:
         return self._run("diff").stdout

